WITH valid_subscriptions AS (SELECT *, ADD_MONTHS(start_date, 6) AS start_date_plus_months FROM subscriptions WHERE plan = 'standard' AND (end_date BETWEEN '2024-11-27' AND '2025-07-05' OR monthly_fee <= 210)), Summary AS (SELECT MONTH(start_date_plus_months) AS start_plus_months_month, MIN(monthly_fee) AS min_monthly_fee, COUNT(CASE WHEN status = 'ACTIVE' THEN 1 END) AS active_count FROM valid_subscriptions GROUP BY MONTH(start_date_plus_months)) SELECT * FROM Summary ORDER BY min_monthly_fee DESC, start_plus_months_month LIMIT 10
